using Essco.Application.Payroll;using Essco.Domain.Payroll;namespace Essco.Tests.Unit.Payroll;public sealed class PayrollTests{[Fact]public async Task Create_rejects_reversed_period(){var r=await new PayrollService(new Repo()).CreateAsync(1,new(2026,2,1),new(2026,1,1),"","u",default);Assert.False(r.Succeeded);Assert.Equal("El rango de fechas es inválido.",r.Error);}[Fact]public void Total_sums_final_salary(){var p=new PayrollRun(1,new(2026,1,1),new(2026,1,15),DateTime.Now,"","u",0,[new("1","A","","",15,100,80,0,0,0,0,0,0),new("2","B","","",15,100,70,0,0,0,0,0,0)]);Assert.Equal(150,p.Total);}private sealed class Repo:IPayrollRepository{public ValueTask<IReadOnlyCollection<PayrollRun>>ListAsync(PayrollFilter f,CancellationToken t)=>ValueTask.FromResult<IReadOnlyCollection<PayrollRun>>([]);public ValueTask<PayrollRun?>GetAsync(int n,CancellationToken t)=>ValueTask.FromResult<PayrollRun?>(null);public ValueTask<(bool Succeeded,int?Number,string?Error)>CreateAsync(int y,DateOnly f,DateOnly u,string c,string s,CancellationToken t)=>ValueTask.FromResult((true,(int?)1,(string?)null));public ValueTask<(bool Succeeded,string?Error)>FinalizeAsync(int n,CancellationToken t)=>ValueTask.FromResult((true,(string?)null));public ValueTask<(bool Succeeded,string?Error)>CancelAsync(int n,CancellationToken t)=>ValueTask.FromResult((true,(string?)null));}}
